mapper.update:
UPDATE sys_employee
SET binding_status = 'BOUND', updated_at = #{now}
WHERE id = #{employeeId}

UPDATE sys_external_identity
SET last_login_at = #{now}, updated_at = #{now}
WHERE provider_type = 'WECHAT'
  AND provider_tenant = #{appId}
  AND provider_subject_hash = #{subjectHash}
  AND status = 'ACTIVE'

UPDATE sys_refresh_token
SET status = 'CONSUMED', consumed_at = #{now}
WHERE id = #{id} AND status = 'ACTIVE'

UPDATE sys_user_session
SET authz_version_at_issue = #{authzVersion},
    idle_expires_at = #{idleExpiresAt}, last_seen_at = #{now}
WHERE id = #{sessionId}

UPDATE sys_user_session
SET idle_expires_at = #{idleExpiresAt}, last_seen_at = #{now}
WHERE id = #{sessionId} AND status = 'ACTIVE'

UPDATE sys_user_session
SET status = 'REVOKED', revoked_at = #{now}, revoke_reason = #{reason}
WHERE id = #{sessionId} AND status = 'ACTIVE'
